import type { FC, MouseEventHandler, ReactNode, Ref } from 'react';
import { Dropdown } from '@patternfly/react-core/dist/dynamic/components/Dropdown';
import { DropdownList } from '@patternfly/react-core/dist/dynamic/components/Dropdown';
import { MenuToggle } from '@patternfly/react-core/dist/dynamic/components/MenuToggle';
import { MenuToggleElement } from '@patternfly/react-core/dist/dynamic/components/MenuToggle';
import { EllipsisVIcon } from '@patternfly/react-icons/dist/dynamic/icons/ellipsis-v-icon';

import { useBoolean } from '../hooks/useBoolean';
import { DataTestIDs } from '../constants/data-test';

const KebabDropdown: FC<{
  dropdownItems: ReactNode;
  onMouseEnter?: MouseEventHandler;
}> = ({ dropdownItems, onMouseEnter }) => {
  const [isOpen, setIsOpen, setOpen, setClosed] = useBoolean(false);

  return (
    <Dropdown
      isOpen={isOpen}
      onSelect={setClosed}
      onOpenChange={(open: boolean) => (open ? setOpen() : setClosed())}
      popperProps={{ position: 'right' }}
      toggle={(toggleRef: Ref<MenuToggleElement>) => (
        <MenuToggle
          ref={toggleRef}
          aria-label="toggle menu"
          data-test-id="kebab-button"
          data-test={DataTestIDs.KebabDropdownButton}
          variant="plain"
          onClick={setIsOpen}
          onMouseEnter={onMouseEnter}
          isExpanded={isOpen}
        >
          <EllipsisVIcon />
        </MenuToggle>
      )}
      shouldFocusToggleOnSelect
    >
      <DropdownList>{dropdownItems}</DropdownList>
    </Dropdown>
  );
};

export default KebabDropdown;
