import * as _ from 'lodash-es';
import type { FC } from 'react';

import {
  Alert,
  DocumentTitle,
  ResourceIcon,
  Timestamp,
} from '@openshift-console/dynamic-plugin-sdk';
import { Breadcrumb } from '@patternfly/react-core/dist/dynamic/components/Breadcrumb';
import { BreadcrumbItem } from '@patternfly/react-core/dist/dynamic/components/Breadcrumb';
import { DescriptionList } from '@patternfly/react-core/dist/dynamic/components/DescriptionList';
import { DescriptionListDescription } from '@patternfly/react-core/dist/dynamic/components/DescriptionList';
import { DescriptionListGroup } from '@patternfly/react-core/dist/dynamic/components/DescriptionList';
import { DescriptionListTerm } from '@patternfly/react-core/dist/dynamic/components/DescriptionList';
import { Divider } from '@patternfly/react-core/dist/dynamic/components/Divider';
import { DropdownItem } from '@patternfly/react-core/dist/dynamic/components/Dropdown';
import { Flex } from '@patternfly/react-core/dist/dynamic/layouts/Flex';
import { FlexItem } from '@patternfly/react-core/dist/dynamic/layouts/Flex';
import { Grid } from '@patternfly/react-core/dist/dynamic/layouts/Grid';
import { GridItem } from '@patternfly/react-core/dist/dynamic/layouts/Grid';
import { PageBreadcrumb } from '@patternfly/react-core/dist/dynamic/components/Page';
import { PageGroup } from '@patternfly/react-core/dist/dynamic/components/Page';
import { PageSection } from '@patternfly/react-core/dist/dynamic/components/Page';
import { Split } from '@patternfly/react-core/dist/dynamic/layouts/Split';
import { SplitItem } from '@patternfly/react-core/dist/dynamic/layouts/Split';
import { Title } from '@patternfly/react-core/dist/dynamic/components/Title';
import { useTranslation } from 'react-i18next';
import {
  getAlertUrl,
  getRuleUrl,
  getSilencesUrl,
  usePerspective,
} from '../../../shared/hooks/usePerspective';
import { useMonitoringNamespace } from '../../../shared/hooks/useMonitoringNamespace';
import KebabDropdown from '../../../shared/components/KebabDropdown';
import { alertDescription, SilenceResource } from '../../../shared/utils/utils';
import { SeverityBadge, SeverityCounts } from '../components/AlertUtils';
import { SilenceDropdown, SilenceMatchersList, SilenceState } from '../components/SilencesUtils';
import { StatusBox } from '../../../shared/console/console-shared/src/components/status/StatusBox';
import { LoadingInline } from '../../../shared/console/console-shared/src/components/loading/LoadingInline';
import withFallback from '../../../shared/console/console-shared/error/fallbacks/withFallback';
import { Table } from '@patternfly/react-table/dist/dynamic/components/Table';
import { TableVariant } from '@patternfly/react-table/dist/dynamic/components/Table';
import { Tbody } from '@patternfly/react-table/dist/dynamic/components/Table';
import { Td } from '@patternfly/react-table/dist/dynamic/components/Table';
import { Th } from '@patternfly/react-table/dist/dynamic/components/Table';
import { Thead } from '@patternfly/react-table/dist/dynamic/components/Table';
import { Tr } from '@patternfly/react-table/dist/dynamic/components/Table';
import { useNavigate, useParams, Link } from 'react-router';
import { MonitoringProvider } from '../../../shared/contexts/MonitoringContext';
import { DataTestIDs } from '../../../shared/constants/data-test';
import { useAlerts } from '../../../shared/hooks/useAlerts';

const SilencesDetailsPage_: FC = () => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);

  const params = useParams<{ id: string }>();
  const { namespace } = useMonitoringNamespace();

  const id = params.id;

  const { silences, rulesAlertLoading } = useAlerts();

  const { perspective } = usePerspective();

  const silence = _.find(silences?.data, { id });

  return (
    <>
      <DocumentTitle>
        {t('{{name}} details', { name: silence?.name || SilenceResource.label })}
      </DocumentTitle>
      <StatusBox
        data={silence}
        label={SilenceResource.label}
        loaded={silences?.loaded}
        loadError={silences?.loadError}
      >
        <PageGroup>
          <PageBreadcrumb hasBodyWrapper={false}>
            <Breadcrumb>
              <BreadcrumbItem>
                <Link
                  to={getSilencesUrl(perspective, namespace)}
                  data-test={DataTestIDs.Breadcrumb}
                >
                  {t('Silences')}
                </Link>
              </BreadcrumbItem>
              <BreadcrumbItem isActive>{t('Silence details')}</BreadcrumbItem>
            </Breadcrumb>
          </PageBreadcrumb>
          <PageSection hasBodyWrapper={false}>
            <Split>
              <SplitItem>
                <Flex>
                  <FlexItem
                    alignSelf={{ default: 'alignSelfCenter' }}
                    spacer={{ default: 'spacerNone' }}
                    data-test={DataTestIDs.SilenceResourceIcon}
                  >
                    <ResourceIcon kind={SilenceResource.kind} />
                  </FlexItem>
                  <FlexItem>
                    <Title headingLevel="h1">{silence?.name}</Title>
                  </FlexItem>
                </Flex>
              </SplitItem>
              <SplitItem isFilled />
              <SplitItem>
                {silence && <SilenceDropdown silence={silence} toggleText={t('Actions')} />}
              </SplitItem>
            </Split>
          </PageSection>
          <Divider />
          <PageSection hasBodyWrapper={false}>
            <Title headingLevel="h2">{t('Silence details')}</Title>
            <Grid sm={12} md={6}>
              <GridItem>
                <DescriptionList>
                  {silence?.name && (
                    <DescriptionListGroup>
                      <DescriptionListTerm>{t('Name')}</DescriptionListTerm>
                      <DescriptionListDescription>{silence?.name}</DescriptionListDescription>
                    </DescriptionListGroup>
                  )}
                  <DescriptionListGroup>
                    <DescriptionListTerm>{t('Matchers')}</DescriptionListTerm>
                    <DescriptionListDescription data-test="label-list">
                      {_.isEmpty(silence?.matchers) ? (
                        <div>{t('No matchers')}</div>
                      ) : (
                        <SilenceMatchersList silence={silence} />
                      )}
                    </DescriptionListDescription>
                  </DescriptionListGroup>
                  <DescriptionListGroup>
                    <DescriptionListTerm>{t('State')}</DescriptionListTerm>
                    <DescriptionListDescription>
                      <SilenceState silence={silence} />
                    </DescriptionListDescription>
                  </DescriptionListGroup>
                  <DescriptionListGroup>
                    <DescriptionListTerm>{t('Last updated at')}</DescriptionListTerm>
                    <DescriptionListDescription>
                      <Timestamp timestamp={silence?.updatedAt} />
                    </DescriptionListDescription>
                  </DescriptionListGroup>
                </DescriptionList>
              </GridItem>
              <GridItem>
                <DescriptionList>
                  <DescriptionListGroup>
                    <DescriptionListTerm>{t('Starts at')}</DescriptionListTerm>
                    <DescriptionListDescription>
                      <Timestamp timestamp={silence?.startsAt} />
                    </DescriptionListDescription>
                  </DescriptionListGroup>
                  <DescriptionListGroup>
                    <DescriptionListTerm>{t('Ends at')}</DescriptionListTerm>
                    <DescriptionListDescription>
                      <Timestamp timestamp={silence?.endsAt} />
                    </DescriptionListDescription>
                  </DescriptionListGroup>
                  <DescriptionListGroup>
                    <DescriptionListTerm>{t('Created by')}</DescriptionListTerm>
                    <DescriptionListDescription>
                      {silence?.createdBy || '-'}
                    </DescriptionListDescription>
                  </DescriptionListGroup>
                  <DescriptionListGroup>
                    <DescriptionListTerm>{t('Comment')}</DescriptionListTerm>
                    <DescriptionListDescription>
                      {silence?.comment || '-'}
                    </DescriptionListDescription>
                  </DescriptionListGroup>
                  <DescriptionListGroup>
                    <DescriptionListTerm>{t('Firing alerts')}</DescriptionListTerm>
                    <DescriptionListDescription>
                      {rulesAlertLoading?.loaded ? (
                        <SeverityCounts alerts={silence?.firingAlerts} />
                      ) : (
                        <LoadingInline />
                      )}
                    </DescriptionListDescription>
                  </DescriptionListGroup>
                </DescriptionList>
              </GridItem>
            </Grid>
          </PageSection>
          <Divider />
          <PageSection hasBodyWrapper={false}>
            <Title headingLevel="h2">{t('Firing alerts')}</Title>
            {rulesAlertLoading?.loaded ? (
              <SilencedAlertsList alerts={silence?.firingAlerts} />
            ) : (
              <LoadingInline />
            )}
          </PageSection>
        </PageGroup>
      </StatusBox>
    </>
  );
};
const SilencesDetailsPageWithFallback = withFallback(SilencesDetailsPage_);

export const MpCmoSilencesDetailsPage = () => {
  return (
    <MonitoringProvider monitoringContext={{ plugin: 'monitoring-plugin', prometheus: 'cmo' }}>
      <SilencesDetailsPageWithFallback />
    </MonitoringProvider>
  );
};

export const McpAcmSilencesDetailsPage = () => {
  return (
    <MonitoringProvider
      monitoringContext={{ plugin: 'monitoring-console-plugin', prometheus: 'acm' }}
    >
      <SilencesDetailsPageWithFallback />
    </MonitoringProvider>
  );
};

const SilencedAlertsList: FC<SilencedAlertsListProps> = ({ alerts }) => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);
  const navigate = useNavigate();
  const { perspective } = usePerspective();
  const { namespace } = useMonitoringNamespace();

  return _.isEmpty(alerts) ? (
    <div>{t('No Alerts found')}</div>
  ) : (
    <Table variant={TableVariant.compact}>
      <Thead>
        <Tr>
          <Th width={80}>{t('Name')}</Th>
          <Th width={20}>{t('Severity')}</Th>
        </Tr>
      </Thead>
      <Tbody>
        {_.sortBy<Alert>(alerts, alertDescription).map((a, i) => (
          <Tr key={i}>
            <Td>
              <Link
                data-test={DataTestIDs.AlertResourceLink}
                to={getAlertUrl(perspective, a, a.rule.id, namespace)}
              >
                {a.labels.alertname}
              </Link>
              <div>{alertDescription(a)}</div>
            </Td>
            <Td>
              <SeverityBadge severity={a.labels.severity} />
            </Td>
            <div>
              <KebabDropdown
                dropdownItems={[
                  <DropdownItem
                    key="view-rule"
                    onClick={() => navigate(getRuleUrl(perspective, a.rule, namespace))}
                  >
                    {t('View alerting rule')}
                  </DropdownItem>,
                ]}
              />
            </div>
          </Tr>
        ))}
      </Tbody>
    </Table>
  );
};

type SilencedAlertsListProps = { alerts: Alert[] };
